from __future__ import annotations

import ast
import calendar
import csv
import json
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATA_DIR = Path(__file__).resolve().parent / "dataset"


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATA_DIR / name).open(newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def _parse_date(value: str) -> date | None:
    """Parse a date, clamping an impossible month-end day to month-end."""
    try:
        return date.fromisoformat(value)
    except ValueError:
        try:
            year_s, month_s, day_s = value.split("-")
            year, month, day = int(year_s), int(month_s), int(day_s)
            last_day = calendar.monthrange(year, month)[1]
            if day > last_day and day <= 31:
                return date(year, month, last_day)
        except (ValueError, TypeError):
            pass
        return None


def _first_weekday(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _period_start(day: date, weekday: int) -> date:
    """Return the first weekday-of-payroll in this or the preceding month."""
    start = _first_weekday(day.year, day.month, weekday)
    if day >= start:
        return start
    if day.month == 1:
        year, month = day.year - 1, 12
    else:
        year, month = day.year, day.month - 1
    return _first_weekday(year, month, weekday)


def answer() -> dict[str, list[int]]:
    employees_rows = _read_csv("employees.csv")
    tasks_rows = _read_csv("tasks.csv")
    timesheet_rows = _read_csv("timesheet.csv")

    employees = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in employees_rows
        if row.get("PESEL") and row.get("hourly_rate")
    }
    task_rates = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in tasks_rows
        if row.get("task_id") and row.get("pay_per_completion")
    }

    parsed_dates = [
        parsed
        for row in timesheet_rows
        if (parsed := _parse_date(row.get("date", ""))) is not None
    ]
    if not parsed_dates:
        return {pesel: [] for pesel in employees}

    # Payroll collection follows the weekday of the earliest valid timesheet.
    payroll_weekday = min(parsed_dates).weekday()
    totals: dict[tuple[str, date], Decimal] = defaultdict(Decimal)
    period_starts: set[date] = set()

    for row in timesheet_rows:
        pesel = row.get("employee_id", "")
        if pesel not in employees:
            # Without a matching employee record there is no reliable hourly rate.
            continue

        work_date = _parse_date(row.get("date", ""))
        if work_date is None:
            continue
        try:
            hours = Decimal(row["hours_worked"])
            if hours < 0:
                continue
        except (KeyError, ValueError):
            continue

        bonus = Decimal(0)
        try:
            performed = ast.literal_eval(row.get("performed_tasks", "[]"))
            if isinstance(performed, (list, tuple)):
                for task_id in performed:
                    try:
                        bonus += task_rates.get(int(task_id), Decimal(0))
                    except (ValueError, TypeError):
                        continue
        except (ValueError, SyntaxError):
            pass

        period = _period_start(work_date, payroll_weekday)
        period_starts.add(period)
        totals[(pesel, period)] += hours * employees[pesel] + bonus

    ordered_periods = sorted(period_starts)
    result: dict[str, list[int]] = {}
    for pesel in employees:
        result[pesel] = [
            int(totals[(pesel, period)].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for period in ordered_periods
        ]
    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, ensure_ascii=False)
